PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,password TEXT NOT NULL,nickname TEXT NOT NULL,avatar TEXT NOT NULL DEFAULT '',banner TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'online',last_seen INTEGER NOT NULL DEFAULT 0,badges TEXT NOT NULL DEFAULT '["初来乍到"]');
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS friends(owner TEXT NOT NULL,friend TEXT NOT NULL,remark TEXT NOT NULL DEFAULT '',PRIMARY KEY(owner,friend));
CREATE TABLE IF NOT EXISTS files(id TEXT PRIMARY KEY,owner TEXT NOT NULL,name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT,sender TEXT NOT NULL,receiver TEXT NOT NULL,kind TEXT NOT NULL,body TEXT NOT NULL,file_id TEXT,forwarded INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,seen INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS messages_pair ON messages(sender,receiver,id);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
CREATE TABLE IF NOT EXISTS user_security(user_id TEXT PRIMARY KEY,role TEXT NOT NULL DEFAULT 'user',banned INTEGER NOT NULL DEFAULT 0,reason TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS badge_defs(id TEXT PRIMARY KEY,name TEXT NOT NULL,image TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_badges(user_id TEXT NOT NULL,badge_id TEXT NOT NULL,PRIMARY KEY(user_id,badge_id));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,created INTEGER NOT NULL);
